function wordBreak(s: string, wordDict: string[]): boolean {
  const n = s.length;
  // Множество для проверки слова за O(1)
  const words = new Set(wordDict);
  // Длина самого длинного слова: дальше назад смотреть бессмысленно
  let maxLen = 0;
  for (const w of wordDict) maxLen = Math.max(maxLen, w.length);

  // dp[i] — можно ли разбить префикс s[0..i) на слова словаря
  const dp: boolean[] = new Array(n + 1).fill(false);
  // Пустой префикс разбивается всегда (ноль слов)
  dp[0] = true;

  for (let i = 1; i <= n; i++) {
    // Перебираем начало j последнего слова s[j..i)
    for (let j = i - 1; j >= Math.max(0, i - maxLen); j--) {
      // Префикс до j разбивается, а s[j..i) — слово из словаря
      if (dp[j] && words.has(s.slice(j, i))) {
        dp[i] = true;
        break; // одного способа достаточно
      }
    }
  }

  return dp[n];
}

// Время: O(n · L²), где L — длина самого длинного слова (L переходов, срез строки за O(L))
// Память: O(n + размер словаря)
